try{const saved=JSON.parse(localStorage.getItem(schoolInfoStorage));if(saved&&Array.isArray(saved.subjects)&&Array.isArray(saved.activities))schoolInfo=saved;}catch{}
const builtInSchoolSubjects=['Matemática','Português','História','Geografia','Ciências','Biologia','Física','Química','Inglês','Programação'];
if(!schoolInfo.defaultsAdded){builtInSchoolSubjects.forEach((name,index)=>{if(!schoolInfo.subjects.some(subject=>subject.name.trim().toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')))schoolInfo.subjects.push({id:`materia-padrao-${index+1}`,name,grade:'',attendance:''});});schoolInfo.defaultsAdded=true;localStorage.setItem(schoolInfoStorage,JSON.stringify(schoolInfo));}
if(!schoolInfo.scheduleImported20260902){const weeklyClasses={1:['Programação Back end','Programação Back end','Português','Português','Matemática','Matemática'],2:['Programação no Desenvolvimento de Sistemas','Programação no Desenvolvimento de Sistemas','Educação Física','Computação Gráfica','Análise e Projeto de Sistemas','Análise e Projeto de Sistemas'],3:['Matemática','Matemática','Educação Financeira','Banco de Dados','Banco de Dados','Análise e Projeto de Sistemas'],4:['Ciência de Dados','Física','Português','Português','Programação no Desenvolvimento de Sistemas','Programação no Desenvolvimento de Sistemas'],5:['Programação Mobile','Programação Mobile','Programação Back end','Banco de Dados','Programação Back end','Ciência de Dados']};const names=[...new Set(Object.values(weeklyClasses).flat())];names.forEach((name,index)=>{if(!schoolInfo.subjects.some(subject=>subject.name.trim().toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')))schoolInfo.subjects.push({id:`materia-cronograma-${index+1}`,name,grade:'',attendance:''});});schoolInfo.schedule=[];Object.entries(weeklyClasses).forEach(([day,classes])=>classes.forEach((name,index)=>{const subject=schoolInfo.subjects.find(item=>item.name.trim().toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR'));schoolInfo.schedule.push({id:`aula-${day}-${index+1}`,day:Number(day),time:`${index+1}ª aula`,subjectId:subject.id});}));schoolInfo.scheduleImported20260902=true;localStorage.setItem(schoolInfoStorage,JSON.stringify(schoolInfo));}
