function applyDailyAttendanceSymbols(){const rows=$$('#schoolSubjectsBody tr'),today=new Date().getDay(),date=localSchoolDate(),todayLessons=(schoolInfo.schedule||[]).filter(item=>Number(item.day)===today);schoolInfo.subjects.forEach((subject,index)=>{const label=rows[index]?.querySelector('.school-attendance');if(!label)return;const subjectLessons=todayLessons.filter(item=>item.subjectId===subject.id);if(!subjectLessons.length){label.textContent='0%';label.className='school-attendance';return}const records=subjectLessons.map(lesson=>(schoolInfo.lessonAttendance||[]).find(item=>item.date===date&&item.scheduleId===lesson.id)).filter(Boolean);if(!records.length)return;const absences=records.filter(item=>item.status==='absent').length,presencePercentage=Math.round((subjectLessons.length-absences)/subjectLessons.length*100);label.textContent=presencePercentage===100?'✓':presencePercentage===0?'✕':`${presencePercentage}%`;label.className=`school-attendance attendance-symbol ${presencePercentage===100?'present':presencePercentage===0?'absent':'partial'}`;});}
function splitSchoolActivities(){const list=$('#schoolActivityList');if(!list||list.querySelector('.school-activity-group'))return;const activities=[...list.querySelectorAll('.school-activity')],groups=[['Trabalho','Trabalhos','📝'],['Prova','Provas','★'],['Passeio','Passeios','🚌']];list.innerHTML=groups.map(([type,title,icon])=>{const items=activities.filter(item=>item.dataset.activityType===type).map(item=>item.outerHTML).join('');return `<section class="school-activity-group"><header><span aria-hidden="true">${icon}</span><h3>${title}</h3><button class="secondary-button" data-add-school-type="${type}">+ Adicionar</button></header><div>${items||`<p class="school-empty">Nenhum ${type.toLocaleLowerCase('pt-BR')} cadastrado.</p>`}</div></section>`}).join('');const card=list.closest('.school-info-card');if(card){card.querySelector('h2').textContent='Agenda escolar';const mainButton=card.querySelector('#addSchoolActivity');if(mainButton)mainButton.classList.add('hidden');}$('#schoolActivitiesEmpty')?.classList.add('hidden');}
function schoolPdfTransaction(mode,action){return new Promise((resolve,reject)=>{const request=indexedDB.open('caderno-digital-passeios',1);request.onupgradeneeded=()=>request.result.createObjectStore('pdfs',{keyPath:'id'});request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,transaction=db.transaction('pdfs',mode),store=transaction.objectStore('pdfs'),result=action(store);transaction.oncomplete=()=>{db.close();resolve(result?.result)};transaction.onerror=()=>reject(transaction.error);};});}
function renderTripPdfs(){const group=$$('.school-activity-group')[2];if(!group)return;let files=group.querySelector('.trip-pdf-list');if(!files){files=document.createElement('div');files.className='trip-pdf-list';group.append(files);}const items=schoolInfo.tripPdfs||[];files.innerHTML=items.length?items.map(file=>`<button data-open-trip-pdf="${file.id}"><span aria-hidden="true">📄</span><strong>${schoolEscape(file.name)}</strong><small>Abrir PDF</small></button>`).join(''):'<p class="school-empty">Nenhum PDF de passeio adicionado.</p>';}
function configureSchoolActivityForm(type){const trip=type==='Passeio',title=$('#schoolActivityTitle'),subject=$('#schoolActivitySubject'),subjectLabel=subject.previousElementSibling,pdfBox=$('#tripPdfBox');title.previousElementSibling.classList.toggle('hidden',trip);title.classList.toggle('hidden',trip);subjectLabel.classList.toggle('hidden',trip);subject.classList.toggle('hidden',trip);pdfBox.classList.toggle('hidden',!trip);title.required=!trip;subject.required=!trip;$('#tripPdfFile').required=trip;}
function schoolGradePoints(value){const grade=Number(String(value).replace(',','.'));return Number.isFinite(grade)?Math.round(grade*10):0;}
function subjectPointsMissing(subject){const grades=[subject.grade,subject.grade2,subject.grade3].filter(value=>value!==''&&value!==undefined&&value!==null).map(schoolGradePoints);return grades.length?Math.max(0,180-grades.reduce((sum,value)=>sum+value,0)):null;}
function renderTrimesterGrades(){const table=$('.school-table');if(!table)return;table.querySelector('thead tr').innerHTML='<th>Matéria</th><th>1º trimestre</th><th>2º trimestre</th><th>3º trimestre</th><th>Falta para 180</th><th>Frequência</th><th><span class="sr-only">Ações</span></th>';$('#schoolSubjectsBody').innerHTML=schoolInfo.subjects.map(subject=>{const grade=value=>value===''||value===undefined?'—':String(schoolGradePoints(value)),missing=subjectPointsMissing(subject);return `<tr><td>${schoolEscape(subject.name)}</td><td><span class="school-grade">${grade(subject.grade)}</span></td><td><span class="school-grade">${grade(subject.grade2)}</span></td><td><span class="school-grade">${grade(subject.grade3)}</span></td><td><strong>${missing===null?'—':missing}</strong></td><td><span class="school-attendance">${subject.attendance===''?'0%':Number(subject.attendance)+'%'}</span></td><td><div class="school-row-actions"><button class="school-icon-button" data-edit-school-subject="${subject.id}" aria-label="Editar ${schoolEscape(subject.name)}">✎</button><button class="school-icon-button delete" data-delete-school-subject="${subject.id}" aria-label="Excluir ${schoolEscape(subject.name)}">×</button></div></td></tr>`}).join('');const missingValues=schoolInfo.subjects.map(subjectPointsMissing).filter(value=>value!==null),summaryLabel=$('#schoolGradeAverage')?.previousElementSibling;if(summaryLabel)summaryLabel.textContent='Falta média para 180';$('#schoolGradeAverage').textContent=missingValues.length?String(Math.trunc(missingValues.reduce((sum,value)=>sum+value,0)/missingValues.length)):'—';applyDailyAttendanceSymbols();}
