window.addEventListener('load',()=>{const form=$('#schoolActivityForm'),actions=form.querySelector('.school-dialog-actions'),box=document.createElement('div');box.id='tripPdfBox';box.className='trip-pdf-box hidden';box.innerHTML='<label for="tripPdfFile">PDF do passeio</label><input id="tripPdfFile" type="file" accept="application/pdf"><small>Escolha o informativo ou autorização do passeio em PDF.</small>';actions.before(box);form.addEventListener('submit',async event=>{if($('#schoolActivityType').value!=='Passeio')return;event.preventDefault();event.stopImmediatePropagation();const file=$('#tripPdfFile').files[0];if(!file)return;const id=crypto.randomUUID();await schoolPdfTransaction('readwrite',store=>store.put({id,name:file.name,blob:file,savedAt:Date.now()}));if(!schoolInfo.tripPdfs)schoolInfo.tripPdfs=[];schoolInfo.tripPdfs.unshift({id,name:file.name});saveSchoolInfo();form.closest('dialog').close();renderTripPdfs();},true);setTimeout(renderTripPdfs);});
window.addEventListener('load',()=>{const grade=$('#schoolSubjectGrade'),row=grade?.closest('.school-form-row');if(!grade||!row)return;grade.previousElementSibling.textContent='Nota do 1º trimestre';grade.type='text';grade.inputMode='decimal';grade.pattern='[0-9]+([,.][0-9]+)?';grade.placeholder='Ex.: 6,5';const attendance=$('#schoolSubjectAttendance');if(attendance){const hiddenAttendance=document.createElement('input');hiddenAttendance.id='schoolSubjectAttendance';hiddenAttendance.type='hidden';hiddenAttendance.value=attendance.value;attendance.closest('div').replaceWith(hiddenAttendance);}const second=document.createElement('div');second.innerHTML='<label for="schoolSubjectGrade2">Nota do 2º trimestre</label><input id="schoolSubjectGrade2" type="text" inputmode="decimal" pattern="[0-9]+([,.][0-9]+)?" placeholder="Ex.: 6,5">';const third=document.createElement('div');third.innerHTML='<label for="schoolSubjectGrade3">Nota do 3º trimestre</label><input id="schoolSubjectGrade3" type="text" inputmode="decimal" pattern="[0-9]+([,.][0-9]+)?" placeholder="Ex.: 6,5">';row.insertBefore(second,row.lastElementChild);row.insertBefore(third,row.lastElementChild);setTimeout(renderTrimesterGrades);});
const saveSchoolInfo=()=>localStorage.setItem(schoolInfoStorage,JSON.stringify(schoolInfo));
function localSchoolDate(){const now=new Date(),year=now.getFullYear(),month=String(now.getMonth()+1).padStart(2,'0'),day=String(now.getDate()).padStart(2,'0');return `${year}-${month}-${day}`;}
function registerSchoolAttendance(status){if(!schoolInfo.attendanceLog)schoolInfo.attendanceLog=[];if(!schoolInfo.lessonAttendance)schoolInfo.lessonAttendance=[];const date=localSchoolDate(),today=new Date().getDay(),existing=schoolInfo.attendanceLog.find(item=>item.date===date),todayLessons=(schoolInfo.schedule||[]).filter(item=>Number(item.day)===today),todaySubjectIds=[...new Set(todayLessons.map(lesson=>lesson.subjectId))];if(existing)existing.status=status;else schoolInfo.attendanceLog.push({date,status});todayLessons.forEach(lesson=>{let record=schoolInfo.lessonAttendance.find(item=>item.date===date&&item.scheduleId===lesson.id);if(record)record.status=status;else schoolInfo.lessonAttendance.push({date,scheduleId:lesson.id,subjectId:lesson.subjectId,status});});todaySubjectIds.forEach(updateSubjectAttendance);schoolInfo.subjects.forEach(subject=>{if(!todaySubjectIds.includes(subject.id))subject.attendance='0';});saveSchoolInfo();renderSchoolInfo();renderDailyAttendance();renderSchoolSchedule();renderAttendanceStats();}
function updateSubjectAttendance(subjectId){const lessons=(schoolInfo.lessonAttendance||[]).filter(item=>item.subjectId===subjectId);if(!lessons.length)return;const subject=schoolInfo.subjects.find(item=>item.id===subjectId);if(subject)subject.attendance=String(Math.round(lessons.filter(item=>item.status==='present').length/lessons.length*100));}
function renderAttendanceStats(){const mount=$('#attendanceStatsMount');if(!mount)return;const records=schoolInfo.lessonAttendance||[],registered=records.length,automaticPresences=records.filter(item=>item.status==='present').length,presences=Math.max(0,automaticPresences+(Number(schoolInfo.presenceAdjustment)||0)),automaticAbsences=records.filter(item=>item.status==='absent').length,absences=Math.max(0,automaticAbsences+(Number(schoolInfo.absenceAdjustment)||0)),held=Number(schoolInfo.classesHeldSoFar)||registered,planned=Number(schoolInfo.totalPlannedLessons)||0,remaining=planned?Math.max(0,Math.floor(planned*.25)-absences):'—';mount.innerHTML=`<article class="attendance-stats-card"><div class="attendance-stats-heading"><div><p class="eyebrow">CONTROLE DE FREQUÊNCIA</p><h2>Resumo de presenças</h2></div><div class="attendance-total-inputs"><label>Aulas que tive até agora <input id="classesHeldSoFar" type="number" min="0" step="1" value="${schoolInfo.classesHeldSoFar??''}" placeholder="Ex.: 80"></label><label>Total de aulas previsto <input id="totalPlannedLessons" type="number" min="1" step="1" value="${planned||''}" placeholder="Ex.: 200"></label></div></div><div class="attendance-stat-grid"><div><small>Presenças</small><strong>${presences}</strong><button class="edit-stat-button" data-edit-presences>Alterar</button></div><div><small>Faltas</small><strong>${absences}</strong><button class="edit-stat-button" data-edit-absences>Alterar</button></div><div><small>Faltas restantes</small><strong>${remaining}</strong></div></div><p class="attendance-rule">As faltas restantes consideram frequência mínima de 75%. Informe o total de aulas previsto para fazer o cálculo.</p></article>`;$('#classesHeldSoFar').onchange=event=>{schoolInfo.classesHeldSoFar=Math.max(0,Number(event.target.value)||0);saveSchoolInfo();renderAttendanceStats()};$('#totalPlannedLessons').onchange=event=>{schoolInfo.totalPlannedLessons=Math.max(0,Number(event.target.value)||0);saveSchoolInfo();renderAttendanceStats()};}
function renderSchoolSchedule(){const mount=$('#schoolScheduleMount');if(!mount)return;if(!schoolInfo.schedule)schoolInfo.schedule=[];const days=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'],today=new Date().getDay(),todayLessons=schoolInfo.schedule.filter(item=>Number(item.day)===today).sort((a,b)=>a.time.localeCompare(b.time)),date=localSchoolDate(),classTime=item=>item.endTime?`${item.time}–${item.endTime}`:item.time;mount.innerHTML=`<article class="school-schedule-card"><div class="school-card-heading"><div><p class="eyebrow">CRONOGRAMA DE AULAS</p><h2>Minha semana</h2></div></div><form id="schoolScheduleForm" class="school-schedule-form"><select id="scheduleDay" aria-label="Dia da aula" required>${days.slice(1,6).map((day,index)=>`<option value="${index+1}">${day}</option>`).join('')}</select><input id="scheduleTime" type="time" aria-label="Início da aula" required><input id="scheduleEndTime" type="time" aria-label="Término da aula" required><select id="scheduleSubject" aria-label="Matéria da aula" required>${schoolInfo.subjects.map(subject=>`<option value="${subject.id}">${schoolEscape(subject.name)}</option>`).join('')}</select><button class="primary-button" type="submit">Adicionar aula</button></form><div class="school-week-list">${schoolInfo.schedule.length?schoolInfo.schedule.sort((a,b)=>a.day-b.day||a.time.localeCompare(b.time)).map(item=>{const subject=schoolInfo.subjects.find(subject=>subject.id===item.subjectId);return `<div><span>${days[item.day]}</span><strong>${classTime(item)} · ${schoolEscape(subject?.name||'Matéria removida')}</strong><button data-delete-schedule="${item.id}" aria-label="Excluir aula">×</button></div>`}).join(''):'<p class="school-empty">Adicione os dias, horários de início e término das suas matérias.</p>'}</div><div class="today-lessons"><h3>Aulas de hoje</h3>${todayLessons.length?todayLessons.map(item=>{const subject=schoolInfo.subjects.find(subject=>subject.id===item.subjectId),record=(schoolInfo.lessonAttendance||[]).find(entry=>entry.date===date&&entry.scheduleId===item.id);return `<div class="today-lesson"><span>${classTime(item)}</span><strong>${schoolEscape(subject?.name||'Matéria removida')}</strong><button class="${record?.status==='present'?'selected':''}" data-lesson-status="present" data-schedule-id="${item.id}">Presente</button><button class="${record?.status==='absent'?'selected absent':''}" data-lesson-status="absent" data-schedule-id="${item.id}">Falta</button></div>`}).join(''):'<p class="school-empty">Nenhuma aula no cronograma de hoje.</p>'}</div></article>`;const form=$('#schoolScheduleForm');form.onsubmit=event=>{event.preventDefault();schoolInfo.schedule.push({id:crypto.randomUUID(),day:Number($('#scheduleDay').value),time:$('#scheduleTime').value,endTime:$('#scheduleEndTime').value,subjectId:$('#scheduleSubject').value});saveSchoolInfo();renderSchoolSchedule()};}
function renderDailyAttendance(){const mount=$('#dailyAttendanceMount');if(!mount)return;const today=localSchoolDate(),weekday=new Date().getDay(),entry=(schoolInfo.attendanceLog||[]).find(item=>item.date===today);if(weekday===0||weekday===6){mount.innerHTML='<div class="daily-attendance done"><span aria-hidden="true">☀</span><div><strong>Hoje não é dia útil</strong><small>O registro automático volta no próximo dia de aula.</small></div></div>';return}if(entry){mount.innerHTML='';return}mount.innerHTML='<div class="daily-attendance"><span aria-hidden="true">🏫</span><div><strong>Você foi à escola hoje?</strong><small>Confirme para atualizar sua frequência automaticamente.</small></div><div class="daily-attendance-actions"><button class="primary-button" data-school-attendance="present">Fui à escola</button><button class="secondary-button" data-school-attendance="absent">Faltei</button></div></div>';}
