document.addEventListener('click',event=>{if(!event.target.closest('[data-edit-presences]'))return;const records=schoolInfo.lessonAttendance||[],automatic=records.filter(item=>item.status==='present').length,current=Math.max(0,automatic+(Number(schoolInfo.presenceAdjustment)||0)),answer=window.prompt('Digite a quantidade correta de presenças:',String(current));if(answer===null)return;const value=Number(answer);if(!Number.isInteger(value)||value<0){window.alert('Digite um número inteiro igual ou maior que zero.');return}schoolInfo.presenceAdjustment=value-automatic;saveSchoolInfo();renderAttendanceStats();});
document.addEventListener('click',event=>{if(!event.target.closest('[data-edit-absences]'))return;const records=schoolInfo.lessonAttendance||[],automatic=records.filter(item=>item.status==='absent').length,current=Math.max(0,automatic+(Number(schoolInfo.absenceAdjustment)||0)),answer=window.prompt('Digite a quantidade correta de faltas:',String(current));if(answer===null)return;const value=Number(answer);if(!Number.isInteger(value)||value<0){window.alert('Digite um número inteiro igual ou maior que zero.');return}schoolInfo.absenceAdjustment=value-automatic;saveSchoolInfo();renderAttendanceStats();});
function renderSchoolInfo(){if(!$('#schoolSubjectsBody'))return;$('#schoolSubjectsBody').innerHTML=schoolInfo.subjects.map(s=>`<tr><td>${schoolEscape(s.name)}</td><td><span class="school-grade">${s.grade===''?'—':Number(s.grade).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})}</span></td><td><span class="school-attendance">${s.attendance===''?'—':Number(s.attendance)+'%'}</span></td><td><div class="school-row-actions"><button class="school-icon-button" data-edit-school-subject="${s.id}" aria-label="Editar ${schoolEscape(s.name)}">✎</button><button class="school-icon-button delete" data-delete-school-subject="${s.id}" aria-label="Excluir ${schoolEscape(s.name)}">×</button></div></td></tr>`).join('');$('#schoolSubjectsEmpty').classList.toggle('hidden',schoolInfo.subjects.length>0);$('#schoolSubjectCount').textContent=schoolInfo.subjects.length;const grades=schoolInfo.subjects.filter(s=>s.grade!=='').map(s=>Number(s.grade)),attendance=schoolInfo.subjects.filter(s=>s.attendance!=='').map(s=>Number(s.attendance));$('#schoolGradeAverage').textContent=grades.length?(grades.reduce((a,b)=>a+b,0)/grades.length).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1}):'—';$('#schoolAttendanceAverage').textContent=attendance.length?Math.round(attendance.reduce((a,b)=>a+b,0)/attendance.length)+'%':'—';$('#schoolPendingCount').textContent=schoolInfo.activities.filter(a=>!a.done).length;$('#schoolActivitySubject').innerHTML=schoolInfo.subjects.map(s=>`<option value="${s.id}">${schoolEscape(s.name)}</option>`).join('');const sorted=[...schoolInfo.activities].sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date));$('#schoolActivityList').innerHTML=sorted.map(a=>{const subject=schoolInfo.subjects.find(s=>s.id===a.subjectId),date=new Date(a.date+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});return `<div class="school-activity ${a.done?'done':''}" data-activity-type="${schoolEscape(a.type)}"><input type="checkbox" ${a.done?'checked':''} data-toggle-school-activity="${a.id}" aria-label="Marcar ${schoolEscape(a.title)} como concluído"><div><strong>${schoolEscape(a.title)}</strong><small>${schoolEscape(subject?.name||'Matéria removida')} · ${date}</small></div><button class="school-icon-button delete" data-delete-school-activity="${a.id}" aria-label="Excluir ${schoolEscape(a.title)}">×</button></div>`}).join('');$('#schoolActivitiesEmpty').classList.toggle('hidden',schoolInfo.activities.length>0);}
function openSchoolSubjectDialog(subject){$('#schoolSubjectDialogTitle').textContent=subject?'Editar matéria':'Nova matéria';$('#schoolSubjectEditId').value=subject?.id||'';$('#schoolSubjectName').value=subject?.name||'';$('#schoolSubjectGrade').value=subject?.grade??'';$('#schoolSubjectAttendance').value=subject?.attendance??'';$('#schoolSubjectDialog').showModal();}
document.addEventListener('click',event=>{const edit=event.target.closest('[data-edit-school-subject]'),remove=event.target.closest('[data-delete-school-subject]'),toggle=event.target.closest('[data-toggle-school-activity]'),removeActivity=event.target.closest('[data-delete-school-activity]');if(edit)openSchoolSubjectDialog(schoolInfo.subjects.find(s=>s.id===edit.dataset.editSchoolSubject));if(remove){schoolInfo.subjects=schoolInfo.subjects.filter(s=>s.id!==remove.dataset.deleteSchoolSubject);saveSchoolInfo();renderSchoolInfo()}if(toggle){const activity=schoolInfo.activities.find(a=>a.id===toggle.dataset.toggleSchoolActivity);if(activity){activity.done=toggle.checked;saveSchoolInfo();renderSchoolInfo()}}if(removeActivity){schoolInfo.activities=schoolInfo.activities.filter(a=>a.id!==removeActivity.dataset.deleteSchoolActivity);saveSchoolInfo();renderSchoolInfo()}});
window.addEventListener('load',()=>{renderSchoolInfo();$('#addSchoolSubject').onclick=()=>openSchoolSubjectDialog();$('#addSchoolActivity').onclick=()=>{if(!schoolInfo.subjects.length){openSchoolSubjectDialog();return}$('#schoolActivityForm').reset();$('#schoolActivityDate').value=new Date().toISOString().slice(0,10);$('#schoolActivityDialog').showModal()};$$('[data-close-school-dialog]').forEach(button=>button.onclick=()=>button.closest('dialog').close());$('#schoolSubjectForm').onsubmit=event=>{event.preventDefault();const id=$('#schoolSubjectEditId').value,data={id:id||crypto.randomUUID(),name:$('#schoolSubjectName').value.trim(),grade:$('#schoolSubjectGrade').value,attendance:$('#schoolSubjectAttendance').value},index=schoolInfo.subjects.findIndex(s=>s.id===id);if(index>=0)schoolInfo.subjects[index]=data;else schoolInfo.subjects.push(data);saveSchoolInfo();renderSchoolInfo();$('#schoolSubjectDialog').close()};$('#schoolActivityForm').onsubmit=event=>{event.preventDefault();schoolInfo.activities.push({id:crypto.randomUUID(),title:$('#schoolActivityTitle').value.trim(),type:$('#schoolActivityType').value,date:$('#schoolActivityDate').value,subjectId:$('#schoolActivitySubject').value,done:false});saveSchoolInfo();renderSchoolInfo();$('#schoolActivityDialog').close()}});
