const focusModeStorage='caderno-digital-focus-mode';
function applyFocusMode(active,announce=false){document.body.classList.toggle('focus-mode',active);$('#focusModeButton').setAttribute('aria-pressed',String(active));$('#focusModeLabel').textContent=active?'Sair do foco':'Modo foco';$('#focusModeButton').querySelector('span[aria-hidden]').textContent=active?'✕':'◎';if(announce)$('#focusModeStatus').textContent=active?'Modo foco ativado. Menus secundários foram ocultados.':'Modo foco desativado. Todos os menus estão visíveis.';try{localStorage.setItem(focusModeStorage,String(active));}catch{}}
applyFocusMode(localStorage.getItem(focusModeStorage)==='true');
$('#focusModeButton').onclick=()=>applyFocusMode(!document.body.classList.contains('focus-mode'),true);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('focus-mode')&&$('#internalSiteViewer')?.classList.contains('hidden')){applyFocusMode(false,true);$('#focusModeButton').focus();}});
const focusScheduleStorage='caderno-digital-focus-schedule';let focusSchedule=[];
try{focusSchedule=JSON.parse(localStorage.getItem(focusScheduleStorage)||'[]');if(!Array.isArray(focusSchedule))focusSchedule=[];}catch{focusSchedule=[];}
function saveFocusSchedule(){try{localStorage.setItem(focusScheduleStorage,JSON.stringify(focusSchedule));}catch{}}
function renderFocusSchedule(){const list=$('#focusScheduleList');if(!focusSchedule.length){list.innerHTML='<p class="focus-schedule-empty">Nenhuma atividade adicionada.</p>';return;}list.innerHTML=[...focusSchedule].sort((a,b)=>a.time.localeCompare(b.time)).map(item=>`<div class="focus-schedule-item ${item.done?'done':''}"><input type="checkbox" data-focus-done="${item.id}" ${item.done?'checked':''} aria-label="Marcar ${escapeHtml(item.task)} como concluída"><span><strong>${escapeHtml(item.task)}</strong><small>${escapeHtml(item.time)} · ${item.duration} minutos</small></span><button type="button" data-focus-delete="${item.id}" aria-label="Excluir ${escapeHtml(item.task)}">✕</button></div>`).join('');$$('[data-focus-done]').forEach(input=>input.onchange=()=>{const item=focusSchedule.find(entry=>entry.id===input.dataset.focusDone);if(item){item.done=input.checked;saveFocusSchedule();renderFocusSchedule();}});$$('[data-focus-delete]').forEach(button=>button.onclick=()=>{focusSchedule=focusSchedule.filter(item=>item.id!==button.dataset.focusDelete);saveFocusSchedule();renderFocusSchedule();$('#focusScheduleStatus').textContent='Atividade excluída do cronograma.';});}
$('#focusScheduleForm').onsubmit=event=>{event.preventDefault();const task=$('#focusTask').value.trim(),time=$('#focusTaskTime').value,duration=Math.max(5,Math.min(240,Number($('#focusTaskDuration').value)||30));if(!task||!time)return;focusSchedule.push({id:crypto.randomUUID(),task,time,duration,done:false});saveFocusSchedule();renderFocusSchedule();event.target.reset();$('#focusTaskDuration').value=30;$('#focusScheduleStatus').textContent='Atividade adicionada ao cronograma.';$('#focusTask').focus();};
$('#toggleFocusSchedule').onclick=()=>{const collapsed=$('#focusSchedule').classList.toggle('collapsed');$('#toggleFocusSchedule').textContent=collapsed?'Expandir':'Recolher';$('#toggleFocusSchedule').setAttribute('aria-expanded',String(!collapsed));};renderFocusSchedule();

const accessibilityStorage='caderno-digital-accessibility';
