function applyCloudAppData(data){if(!data||typeof data!=='object')return false;let changed=false;Object.entries(data).forEach(([key,value])=>{if(!key.startsWith('caderno-digital-')||cloudStorageExclusions.has(key)||typeof value!=='string')return;if(localStorage.getItem(key)!==value){localStorage.setItem(key,value);changed=true;}});return changed;}
