function mergeNotebookCollections(remoteNotebooks,localNotebooks){const merged=[],seenIds=new Set(),seenContent=new Set();let starterIndex=-1;for(const source of [removeThreeUnwantedNotebooks(remoteNotebooks),removeThreeUnwantedNotebooks(localNotebooks)])for(const original of source||[]){if(!original||!Array.isArray(original.pages))continue;const notebook=JSON.parse(JSON.stringify(original));if(!notebook.id)notebook.id=crypto.randomUUID();const contentKey=JSON.stringify({title:notebook.title||'',cover:notebook.cover||'',paperType:notebook.paperType||'',pages:notebook.pages}),isStarter=(notebook.title||'').trim().toLocaleLowerCase('pt-BR')==='meu caderno';if(isStarter&&starterIndex>=0){const current=merged[starterIndex],currentSize=JSON.stringify(current.pages||[]).length,newSize=JSON.stringify(notebook.pages||[]).length;if(newSize>currentSize){seenIds.delete(current.id);merged[starterIndex]=notebook;seenIds.add(notebook.id);}continue}if(seenIds.has(notebook.id)||seenContent.has(contentKey))continue;seenIds.add(notebook.id);seenContent.add(contentKey);merged.push(notebook);if(isStarter)starterIndex=merged.length-1;}return merged;}
async function startGoogleLogin(){saveCurrent();if(!cloudAuth){setCloudStatus('A conexão com a nuvem ainda está carregando. Tente novamente em alguns segundos.');return;}if(cloudUser){await cloudAuth.signOut();return;}setCloudStatus('Abrindo a página segura do Google...');const provider=new firebase.auth.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});try{await cloudAuth.signInWithPopup(provider);}catch(error){if(['auth/popup-blocked','auth/operation-not-supported-in-this-environment'].includes(error?.code)){setCloudStatus('Abrindo o Google em uma página segura...');try{await cloudAuth.signInWithRedirect(provider);return;}catch{}}setCloudStatus(error?.code==='auth/popup-closed-by-user'?'A janela do Google foi fechada antes de concluir a entrada.':'O Google não concluiu a entrada. Atualize a página e tente novamente.');}}
$('#sideGoogleLogin').onclick=startGoogleLogin;
if(window.firebase){firebase.initializeApp(firebaseConfig);cloudAuth=firebase.auth();cloudDb=firebase.firestore();cloudAuth.useDeviceLanguage();cloudAuth.getRedirectResult().catch(error=>setCloudStatus(error.code==='auth/unauthorized-domain'?'Este endereço ainda não foi autorizado para entrar com Google.':'O Google não concluiu a entrada. Toque no botão e tente novamente.'));cloudAuth.onAuthStateChanged(async user=>{if(cloudUnsubscribe){cloudUnsubscribe();cloudUnsubscribe=null;}cloudUser=user;cloudReady=false;if(!user){$('#sideGoogleLogin').innerHTML='<span aria-hidden="true">G</span> Continuar com Google';setCloudStatus('Entre com Google para sincronizar computador, celular e tablet.');return;}$('#sideGoogleLogin').textContent='Sair da nuvem';setCloudStatus('Sincronizando os dados deste aparelho com a nuvem...');const documentRef=cloudDb.collection('users').doc(user.uid);try{const snapshot=await documentRef.get(),remoteData=snapshot.data()||{},remoteNotebooks=snapshot.exists?remoteData.notebooks:[],appDataChanged=applyCloudAppData(remoteData.appData),reloadKey=`caderno-digital-cloud-loaded-${user.uid}`;if(appDataChanged&&!sessionStorage.getItem(reloadKey)){sessionStorage.setItem(reloadKey,'true');location.reload();return;}notebooks=mergeNotebookCollections(remoteNotebooks,notebooks);showCloudNotebooks(notebooks);lastCloudAppData=JSON.stringify(collectCloudAppData());cloudReady=true;await saveNotebooksToCloud();setCloudStatus('✓ Dados sincronizados no computador, celular e tablet.');cloudUnsubscribe=documentRef.onSnapshot(remote=>{const data=remote.data();if(!remote.exists||remote.metadata.hasPendingWrites||data?.updatedBy===cloudClientId)return;const appChanged=applyCloudAppData(data?.appData);if(Array.isArray(data?.notebooks)){const combined=mergeNotebookCollections(data.notebooks,notebooks),received=combined.length>notebooks.length;showCloudNotebooks(combined);if(received)scheduleCloudSave();}lastCloudAppData=JSON.stringify(collectCloudAppData());setCloudStatus(appChanged?'✓ Novos dados recebidos. Atualize a página para exibi-los.':'✓ Alterações recebidas de outro aparelho.');},()=>setCloudStatus('A sincronização em tempo real foi interrompida. Verifique sua internet.'));}catch{cloudReady=true;setCloudStatus('Conta conectada, mas a nuvem ainda não respondeu. Tente novamente em instantes.');}});}
else setCloudStatus('Não foi possível carregar a conexão com a nuvem. Verifique sua internet.');
