window.addEventListener('load',()=>{const card=$('#ia .ai-card');if(!card)return;const saved=JSON.parse(localStorage.getItem('caderno-digital-tutor-context')||'{}'),context=document.createElement('section');context.className='tutor-context';context.innerHTML=`<div><p class="eyebrow">CONTEXTO DE ESTUDO</p><h2>O que você está estudando?</h2></div><label>Nível<select id="tutorLevel"><option>Ensino escolar</option><option>Curso técnico</option><option>Faculdade</option><option>Pós-graduação</option></select></label><label>Curso<input id="tutorCourse" list="tutorCourseList" placeholder="Digite ou escolha um curso"><datalist id="tutorCourseList">${tutorCourses.map(item=>`<option value="${item}">`).join('')}</datalist></label><label>Matéria<input id="tutorSubject" list="tutorSubjectList" placeholder="Digite ou escolha uma matéria"><datalist id="tutorSubjectList">${tutorSubjects.map(item=>`<option value="${item}">`).join('')}</datalist></label>`;card.after(context);$('#tutorLevel').value=saved.level||'Ensino escolar';$('#tutorCourse').value=saved.course||'';$('#tutorSubject').value=saved.subject||'';context.onchange=()=>localStorage.setItem('caderno-digital-tutor-context',JSON.stringify({level:$('#tutorLevel').value,course:$('#tutorCourse').value,subject:$('#tutorSubject').value}));context.oninput=context.onchange;});
function reply(question){const q=question.toLowerCase(),level=$('#tutorLevel')?.value||'seu nível',course=$('#tutorCourse')?.value.trim(),subject=$('#tutorSubject')?.value.trim(),context=[subject,course,level].filter(Boolean).join(' · ');if(q.includes('fotossíntese'))return answers.fotossíntese;if(q.includes('equação')||q.includes('primeiro grau'))return answers.equação;if(q.includes('resumo'))return answers.resumo;if(q.includes('alura'))return answers.alura;if(q.includes('duolingo'))return answers.duolingo;if(q.includes('banco de dados'))return 'Banco de dados organiza informações em tabelas relacionadas. Comece por entidades, atributos, chaves primárias e estrangeiras; depois pratique consultas SQL com SELECT, WHERE, JOIN e GROUP BY.';if(q.includes('algoritmo')||q.includes('programação'))return 'Em programação, transforme o problema em passos: identifique entradas e saídas, escreva o algoritmo, teste casos simples e só então programe. Posso explicar código, lógica, funções, orientação a objetos, back end ou mobile.';if(q.includes('anatomia')||q.includes('fisiologia'))return 'Anatomia estuda as estruturas do corpo; fisiologia explica como elas funcionam. Organize o estudo por sistemas, relacionando cada órgão à sua função e aos principais processos.';if(q.includes('direito'))return 'Para estudar Direito, identifique a norma aplicável, seus requisitos, as exceções e um caso concreto. Posso ajudar a resumir conceitos e comparar institutos jurídicos, sem substituir orientação profissional.';return `Vou considerar este contexto: ${context}. Posso explicar conceitos, criar exemplos, resumir conteúdos, montar exercícios e preparar revisões. Para uma resposta mais precisa, diga o tema específico e qual parte você não entendeu.`;}
function addMessage(text,type,question=''){const m=document.createElement('div');m.className='message '+type;const content=document.createElement('span');content.textContent=text;m.append(content);if(type==='luma'&&question){const save=document.createElement('button');save.className='save-response-card';save.textContent='＋ Salvar como flashcard';save.onclick=()=>addResponseCard(question,text);m.append(save);}$('#chatBox').append(m);$('#chatBox').scrollTop=$('#chatBox').scrollHeight;}
