function renderResponseCards(){$('#responseCards').innerHTML=responseCards.length?responseCards.map(card=>`<article class="response-card flashcard" data-flashcard="${card.id}"><span class="flashcard-side-label">FRENTE</span><div class="flashcard-front"><h3>${escapeHtml(card.question)}</h3></div><div class="flashcard-back hidden"><p>${escapeHtml(card.answer)}</p></div><button class="flip-flashcard" data-flip-card="${card.id}" aria-expanded="false">↻ Ver verso</button><div class="flashcard-card-actions"><button data-edit-card="${card.id}">Editar</button><button data-remove-card="${card.id}" aria-label="Excluir flashcard ${escapeHtml(card.question)}">Excluir</button></div></article>`).join(''):'<p class="small-status">Nenhum flashcard salvo ainda.</p>';$$('[data-flip-card]').forEach(button=>button.onclick=()=>{const card=$(`[data-flashcard="${button.dataset.flipCard}"]`),showingBack=!card.querySelector('.flashcard-back').classList.contains('hidden');card.querySelector('.flashcard-front').classList.toggle('hidden',!showingBack);card.querySelector('.flashcard-back').classList.toggle('hidden',showingBack);card.querySelector('.flashcard-side-label').textContent=showingBack?'FRENTE':'VERSO';button.textContent=showingBack?'↻ Ver verso':'↻ Ver frente';button.setAttribute('aria-expanded',String(!showingBack));});$$('[data-edit-card]').forEach(button=>button.onclick=()=>{const card=responseCards.find(item=>item.id===button.dataset.editCard);if(!card)return;const question=prompt('Frente do flashcard:',card.question);if(!question?.trim())return;const answer=prompt('Verso do flashcard:',card.answer);if(!answer?.trim())return;card.question=question.trim();card.answer=answer.trim();localStorage.setItem(responseCardsStorage,JSON.stringify(responseCards));renderResponseCards();});$$('[data-remove-card]').forEach(button=>button.onclick=()=>{responseCards=responseCards.filter(card=>card.id!==button.dataset.removeCard);localStorage.setItem(responseCardsStorage,JSON.stringify(responseCards));renderResponseCards();});}
function addResponseCard(question,answer){responseCards.unshift({id:crypto.randomUUID(),question,answer});localStorage.setItem(responseCardsStorage,JSON.stringify(responseCards));renderResponseCards();$('#clearResponseCards').textContent='Flashcard salvo!';setTimeout(()=>$('#clearResponseCards').textContent='Limpar flashcards',1200);}
const addFlashcardButton=document.createElement('button');addFlashcardButton.id='addFlashcard';addFlashcardButton.className='primary-button';addFlashcardButton.textContent='＋ Adicionar um Flashcard';$('#clearResponseCards').before(addFlashcardButton);
const flashcardCount=document.createElement('p');flashcardCount.id='flashcardCount';flashcardCount.className='flashcard-count';flashcardCount.setAttribute('aria-live','polite');$('#responseCards').before(flashcardCount);function updateFlashcardCount(){flashcardCount.textContent=`${responseCards.length} flashcard${responseCards.length===1?' disponível':'s disponíveis'}`;}new MutationObserver(updateFlashcardCount).observe($('#responseCards'),{childList:true});updateFlashcardCount();
document.body.insertAdjacentHTML('beforeend','<dialog id="flashcardBatchDialog" class="flashcard-batch-dialog"><form method="dialog"><h2>Adicionar Flashcards</h2><p>Escolha quantos cartões deseja criar.</p><label for="flashcardQuantity">Quantidade</label><select id="flashcardQuantity"><option value="10">10 flashcards</option><option value="20">20 flashcards</option><option value="30">30 flashcards</option></select><label for="flashcardTopic">Assunto dos cartões</label><input id="flashcardTopic" maxlength="80" placeholder="Ex.: Fotossíntese" required><div><button value="cancel" class="secondary-button">Cancelar</button><button id="createFlashcardBatch" value="default" class="primary-button">Criar flashcards</button></div></form></dialog>');
addFlashcardButton.onclick=()=>{$('#flashcardBatchDialog').showModal();$('#flashcardTopic').focus();};
async function generateTopicFlashcards(topic,quantity){const endpoint='https://pt.wikipedia.org/w/api.php?'+new URLSearchParams({action:'query',generator:'search',gsrsearch:topic,gsrlimit:'6',prop:'extracts',explaintext:'1',exintro:'1',format:'json',origin:'*'}),response=await fetch(endpoint),data=await response.json(),pages=Object.values(data.query?.pages||{}),stopWords=new Set(['sobre','entre','também','ainda','desde','foram','forma','parte','quando','onde','como','para','pela','pelos','pelas','mais','muito','uma','alguns','algumas','possui','podem','sendo']);const candidates=[];for(const page of pages){const sentences=(page.extract||'').replace(/\([^)]*\)/g,'').split(/(?<=[.!?])\s+/).map(sentence=>sentence.trim()).filter(sentence=>sentence.length>=45&&sentence.length<=320);if(sentences[0])candidates.push({question:`O que é ${page.title}?`,answer:sentences[0]});for(const sentence of sentences.slice(1)){const words=sentence.match(/[A-Za-zÀ-ÖØ-öø-ÿ]{6,}/g)||[],keyword=words.filter(word=>!stopWords.has(word.toLowerCase())).sort((a,b)=>b.length-a.length)[0];if(!keyword)continue;candidates.push({question:`Complete a frase sobre ${topic}: ${sentence.replace(keyword,'_____')}`,answer:`${keyword}. Frase completa: ${sentence}`});}}if(!candidates.length)throw new Error('no-content');return Array.from({length:quantity},(_,index)=>({id:crypto.randomUUID(),...candidates[index%candidates.length],source:'Wikipédia'}));}
function fallbackTopicFlashcards(topic,quantity){const prompts=['O que é','Qual é a definição de','Quais são as principais características de','Por que é importante estudar','Dê um exemplo relacionado a','Quais são as partes principais de','Como funciona','Quais são as causas de','Quais são as consequências de','Faça um resumo de'];return Array.from({length:quantity},(_,index)=>({id:crypto.randomUUID(),question:`${prompts[index%prompts.length]} ${topic}?`,answer:`Revise suas anotações sobre ${topic} e edite este verso com a resposta.`}));}
$('#flashcardBatchDialog').addEventListener('close',async()=>{if($('#flashcardBatchDialog').returnValue!=='default')return;const quantity=Number($('#flashcardQuantity').value),topic=$('#flashcardTopic').value.trim();if(!topic||![10,20,30].includes(quantity))return;flashcardCount.textContent=`Gerando ${quantity} flashcards sobre ${topic}...`;addFlashcardButton.disabled=true;let cards;try{cards=await generateTopicFlashcards(topic,quantity);}catch{cards=fallbackTopicFlashcards(topic,quantity);}responseCards.unshift(...cards);localStorage.setItem(responseCardsStorage,JSON.stringify(responseCards));renderResponseCards();$('#flashcardTopic').value='';addFlashcardButton.disabled=false;addFlashcardButton.textContent='＋ Adicionar mais Flashcards';setTimeout(()=>flashcardCount.textContent=`✓ ${quantity} flashcards sobre ${topic} criados · ${responseCards.length} no total`,0);});
$('#clearResponseCards').onclick=()=>{if(!responseCards.length||!confirm('Deseja apagar todos os flashcards?'))return;responseCards=[];localStorage.setItem(responseCardsStorage,'[]');renderResponseCards();};
function renderStudyPlan(){$('#studyPlanList').innerHTML=studyPlan.length?studyPlan.map(item=>`<div class="study-plan-item ${item.done?'done':''}"><input type="checkbox" data-plan-done="${item.id}" ${item.done?'checked':''} aria-label="Concluir ${escapeHtml(item.task)}"><strong>${escapeHtml(item.day)}</strong><span>${escapeHtml(item.task)}</span><button data-remove-plan="${item.id}" aria-label="Excluir atividade ${escapeHtml(item.task)}">✕</button></div>`).join(''):'<p class="small-status">Seu plano está vazio. Adicione a primeira atividade.</p>';$$('[data-plan-done]').forEach(input=>input.onchange=()=>{const item=studyPlan.find(entry=>entry.id===input.dataset.planDone);item.done=input.checked;localStorage.setItem(studyPlanStorage,JSON.stringify(studyPlan));renderStudyPlan();});$$('[data-remove-plan]').forEach(button=>button.onclick=()=>{studyPlan=studyPlan.filter(item=>item.id!==button.dataset.removePlan);localStorage.setItem(studyPlanStorage,JSON.stringify(studyPlan));renderStudyPlan();});}
$('#studyPlanForm').onsubmit=event=>{event.preventDefault();const task=$('#studyTask').value.trim();if(!task)return;studyPlan.push({id:crypto.randomUUID(),task,day:$('#studyDay').value,done:false});localStorage.setItem(studyPlanStorage,JSON.stringify(studyPlan));$('#studyTask').value='';renderStudyPlan();};
