function renderPlatformDashboard(platform='alura'){const dashboard=platform==='alura'?$('#platformDashboard'):$('#duolingoDashboard');if(!dashboard)return;if(platform==='alura'){const progress=Math.max(0,Math.min(100,Number(platformProgress.aluraProgress)||0));dashboard.innerHTML=`<article class="platform-dashboard-card"><h3>Painel Alura</h3><p><strong>Conta:</strong> ${platformProgress.aluraEmail?escapeHtml(platformProgress.aluraEmail):'Nenhum e-mail informado'}</p><p><strong>Progresso registrado:</strong> ${progress}%</p><div class="progress-track" role="progressbar" aria-label="Progresso na Alura" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><span style="width:${progress}%"></span></div></article>`;}else{const hasProgress=platformProgress.duolingoProgress!==''&&platformProgress.duolingoProgress!=null,progress=Math.max(0,Math.min(100,Number(platformProgress.duolingoProgress)||0));dashboard.innerHTML=`<article class="platform-dashboard-card"><h3>Painel Duolingo</h3><p><strong>Conta:</strong> ${platformProgress.duolingoEmail?escapeHtml(platformProgress.duolingoEmail):'Nenhum e-mail informado'}</p><p><strong>Progresso registrado:</strong> ${hasProgress?progress+'%':'Nenhum progresso informado'}</p>${hasProgress?`<div class="progress-track" role="progressbar" aria-label="Progresso no Duolingo" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><span style="width:${progress}%"></span></div>`:''}</article>`;}}
async function loadAccountProgress(user){if(!user||!cloudDb)return;try{const snapshot=await cloudDb.collection('users').doc(user.uid).get(),saved=snapshot.data()?.platformProgress;if(saved){platformProgress={...platformProgress,...saved};localStorage.setItem(platformProgressStorage,JSON.stringify(platformProgress));$('#aluraEmail').value=platformProgress.aluraEmail||'';$('#aluraProgress').value=platformProgress.aluraProgress||'';$('#duolingoEmail').value=platformProgress.duolingoEmail||'';$('#duolingoProgress').value=platformProgress.duolingoProgress||'';renderPlatformDashboard('duolingo');$('#platformSyncStatus').textContent='✓ Dados de estudo carregados automaticamente da sua conta.';}}catch{}}
